package br.com.portal.controller;
import br.com.portal.dto.*; import br.com.portal.model.Turma; import br.com.portal.service.TurmaService; import br.com.portal.service.AuthService; import jakarta.servlet.http.HttpSession; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/turmas") public class TurmaController {private final TurmaService service; private final AuthService auth; public TurmaController(TurmaService s,AuthService a){service=s;auth=a;}
 @GetMapping List<Turma> listar(HttpSession s){return service.listar(s);} @GetMapping("/{id}") Turma buscar(@PathVariable Long id,HttpSession s){return service.buscar(id,s);} @GetMapping("/instrutor/{id}") List<Turma> porInstrutor(@PathVariable Long id,HttpSession s){if(!auth.usuarioAtual(s).getId().equals(id)) throw new br.com.portal.exception.RegraNegocioException("Acesso não autorizado."); return service.listar(s);} 
 @PostMapping ResponseEntity<Turma> criar(@Valid @RequestBody TurmaRequest r,HttpSession s){return ResponseEntity.status(201).body(service.criar(r,s));}
 @PutMapping("/{id}") Turma atualizar(@PathVariable Long id,@Valid @RequestBody TurmaRequest r,HttpSession s){return service.atualizar(id,r,s);} @DeleteMapping("/{id}") ResponseEntity<Void> excluir(@PathVariable Long id,HttpSession s){service.excluir(id,s);return ResponseEntity.noContent().build();}}
